              ' · continuing] · ';
    var line =
        '$foldBadge$cwd · ctx $pct% '
        '(${_formatTokenCount(contextTokens)}/${_formatTokenCount(window)}) · '
        '${_formatTokenCount(totalTokens)}tok'
        '$costPart · turn ${_usage.turns}$ratePart$badge · '
        '${_statusProviderLabel(model)}/${model.id}'
