        'by the host, not by you; you did not run it):',
      )
      ..writeln('`$command`')
      ..writeln('exit code: $exitCode');
    if (tail.isNotEmpty) {
      buffer
        ..writeln('output (tail):')
        ..writeln('```')
        ..writeln(tail)
        ..writeln('```');
    }
    buffer.writeln('</system-notice>');
    return buffer.toString();
  }

