// Reproduces LiveTokenRateMeter.tokensPerSecond math on a realistic stream:
// 50 t/s true rate (10-tok deltas every 200ms), band read every 16ms.
class Sample { final int tMs; final double tokens; Sample(this.tMs, this.tokens); }
void main() {
  final samples = <Sample>[];
  double windowTokens = 0;
  const windowMs = 5000;
  void count(int tMs, double tokens) {
    samples.add(Sample(tMs, tokens));
    windowTokens += tokens;
    final cutoff = tMs - windowMs;
    while (samples.isNotEmpty && samples.first.tMs <= cutoff) {
      windowTokens -= samples.removeFirst().tokens;
    }
  }
  double? rate(int nowMs) {
    final cutoff = nowMs - windowMs;
    while (samples.isNotEmpty && samples.first.tMs <= cutoff) {
      windowTokens -= samples.removeFirst().tokens;
    }
    if (samples.isEmpty) return null;
    final span = nowMs - samples.first.tMs;
    if (span <= 0) return null;
    return windowTokens * 1000 / span;
  }
  // deltas: 10 tok at t=0,200,400,600,800 (true rate 50 t/s)
  final deltas = {0: 10.0, 200: 10.0, 400: 10.0, 600: 10.0, 800: 10.0};
  for (var t = 0; t <= 1000; t += 16) {
    final d = deltas[t]; // coarse: apply delta at the first frame >= its time
    for (final dt in deltas.keys) {
      if (dt >= (t - 16) && dt < t) count(dt, deltas[dt]!);
    }
    if (d != null) count(t, d);
    final r = rate(t);
    if (r != null) print('t=$t ms  ->  ${r.toStringAsFixed(1)} t/s');
  }
}
EOF
